{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-baccaee0bd9518df","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t  6. Epic-size overage triggers: when the decomposition summary itself\n28\t     acknowledges an epic above the ~2-week size guideline, the summary must\n29\t     also carry a re-split trigger — the concrete planning condition under\n30\t     which the epic should be re-split. An overage left as a bare \"noted for\n31\t     planning awareness\" note is an unresolved defect the review re-docks;\n32\t     an overage with a trigger is a managed trade-off.\n33\t\n34\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n35\t\n36\tUsage:\n37\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n38\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n39\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n40\t\"\"\"\n41\t\n42\timport argparse\n43\timport os\n44\timport re\n45\timport sys\n46\t\n47\timport yaml\n48\t\n49\tSECTIONS = [(\"Description\", (\"description\",)),\n50\t            (\"Scope\", (\"scope\",)),\n51\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n52\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n53\t\n54\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n55\t\n56\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n57\t           \"repo-onboarding\")\n58\t\n59\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n60\t# way) — parity with the implementation_type_rules judge.\n61\tPARALLEL_PAIRS = {\n62\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n63\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n64\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n65\t}\n66\t\n67\t# Check 6 — a sentence acknowledging an epic over the size guideline\n68\t# (\"above/exceeds/over ... guideline/2-week/sprint\"), excluding negated\n69\t# affirmations (\"no epic exceeds\", \"stays within the guideline\").\n70\tOVER_PAT = re.compile(\n71\t    r'\\b(above|exceeds?|exceeding|over|larger than|bigger than)\\b[^.\\n]{0,120}'\n72\t    r'\\b(2-week|two-week|guideline|sprint|epic[- ]size|size guideline)\\b',\n73\t    re.I)\n74\tNEG_PAT = re.compile(\n75\t    r'\\b(no epic|none|within|under|not exceed|doesn?t exceed|'\n76\t    r'do(es)? not exceed|stays? within|below|smaller|fewer than|at most)\\b',\n77\t    re.I)\n78\t# A re-split trigger: a conditional that names the planning condition under\n79\t# which the epic should be re-split.\n80\tTRIG_PAT = re.compile(\n81\t    r're-split|resplit|split[^.\\n]{0,80}\\bif\\b|\\bif\\b[^.\\n]{0,100}'\n82\t    r'(exceed|finds?|grow|outgrow|materially|more (sites|files|calls|than))|'\n83\t    r'trigger', re.I)\n84\t\n85\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n86\t\n87\t\n88\tdef read_frontmatter(path):\n89\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n90\t    with open(path, encoding=\"utf-8\") as f:\n91\t        content = f.read()\n92\t    m = FRONTMATTER_RE.match(content)\n93\t    if not m:\n94\t        return {}, content\n95\t    try:\n96\t        data = yaml.safe_load(m.group(1))\n97\t    except yaml.YAMLError:\n98\t        return {}, content\n99\t    if not isinstance(data, dict):\n100\t        return {}, content\n101\t    return data, content[m.end():]\n102\t\n103\t\n104\tdef body_headings(body):\n105\t    heads = []\n106\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n107\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n108\t    return heads\n109\t\n110\t\n111\tdef load_epics(artifacts_dir, strat_id):\n112\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n113\t\n114\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n115\t    \"\"\"\n116\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n117\t    if not os.path.isdir(task_dir):\n118\t        return {}\n119\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n120\t    epics = {}\n121\t    for name in sorted(os.listdir(task_dir)):\n122\t        m = pat.match(name)\n123\t        if not m:\n124\t            continue\n125\t        path = os.path.join(task_dir, name)\n126\t        fm, body = read_frontmatter(path)\n127\t        epics[name[:-3]] = (path, fm, body)\n128\t    return epics\n129\t\n130\t\n131\tdef dependency_closure(start_key, deps):\n132\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n133\t    seen, stack = set(), list(deps.get(start_key, []))\n134\t    while stack:\n135\t        n = stack.pop()\n136\t        if n in seen or n not in deps:\n137\t            continue\n138\t        seen.add(n)\n139\t        stack.extend(deps[n])\n140\t    return seen\n141\t\n142\t\n143\tdef check_oversize_trigger(artifacts_dir, strat_id):\n144\t    \"\"\"Check 6: a summary that acknowledges an epic above the size guideline\n145\t    must carry a re-split trigger somewhere in the summary. Judge parity: the\n146\t    dq grader docks an acknowledged overage left as a bare planning note and\n147\t    scores full marks when the overage carries a conditional re-split\n148\t    trigger. Returns a list of violation strings.\"\"\"\n149\t    path = os.path.join(artifacts_dir, \"epic-tasks\",\n150\t                        strat_id + \"-decomposition.md\")\n151\t    if not os.path.isfile(path):\n152\t        return []\n153\t    with open(path, encoding=\"utf-8\") as f:\n154\t        summary = f.read()\n155\t    sentences = re.split(r'(?<=[.!?])\\s+|\\n', summary)\n156\t    overage = [s.strip() for s in sentences\n157\t               if OVER_PAT.search(s) and not NEG_PAT.search(s)]\n158\t    if overage and not TRIG_PAT.search(summary):\n159\t        return [\"summary acknowledges an epic above the size guideline \"\n160\t                \"(\\\"...%s...\\\") with no re-split trigger — record the \"\n161\t                \"concrete planning condition under which the epic should be \"\n162\t                \"re-split (e.g. \\\"re-split along